import React from 'react';
import { 
  CheckCircle2, 
  XCircle, 
  Moon, 
  CalendarPlus, 
  Send, 
  LayoutList, 
  Flame,
  Award
} from 'lucide-react';
import { DayData, Task, TomorrowPlan } from '../types';

interface NightReviewProps {
  dayData: DayData;
  onComplete: (note: string, plan: TomorrowPlan) => void;
  onClose: () => void;
}

const NightReview: React.FC<NightReviewProps> = ({ 
  dayData, 
  onComplete, 
  onClose 
}) => {
  const [note, setNote] = React.useState('');
  const [plan, setPlan] = React.useState<TomorrowPlan>({
    englishTopic: '',
    tradingStrategy: '',
    dsaTopic: '',
    flutterReactChapter: ''
  });

  const completedCount = dayData.tasks.filter(t => t.completed).length;
  const totalCount = dayData.tasks.length;
  const percentage = Math.round((completedCount / totalCount) * 100);

  const getPerformanceGrade = (p: number) => {
    if (p >= 95) return { grade: 'A+', color: 'text-green-400', desc: 'Elite Performance!' };
    if (p >= 85) return { grade: 'A', color: 'text-emerald-400', desc: 'Excellent Work!' };
    if (p >= 70) return { grade: 'B', color: 'text-blue-400', desc: 'Great Progress.' };
    if (p >= 50) return { grade: 'C', color: 'text-yellow-400', desc: 'Needs Consistency.' };
    return { grade: 'F', color: 'text-red-400', desc: 'Highly Disappointing.' };
  };

  const performance = getPerformanceGrade(percentage);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-md" onClick={onClose} />

      <div className="relative w-full max-w-4xl glass-card border-white/10 overflow-hidden flex flex-col md:flex-row h-full max-h-[85vh]">
        {/* Left Panel: Review */}
        <div className="w-full md:w-5/12 bg-gradient-to-br from-blue-600/10 to-transparent p-8 border-r border-white/5 overflow-y-auto scrollbar-thin">
          <div className="flex items-center gap-3 mb-8">
            <div className="w-10 h-10 rounded-xl bg-blue-600/20 flex items-center justify-center text-blue-400">
              <Moon size={20} />
            </div>
            <div>
              <h2 className="text-xl font-bold">Night Review</h2>
              <p className="text-[10px] text-slate-400 uppercase tracking-widest font-bold">Closure & Reflection</p>
            </div>
          </div>

          <div className="space-y-6 mb-8">
            <div className="glass-card p-4 border-white/10 bg-white/5">
              <div className="flex justify-between items-center mb-4">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">Today's Score</span>
                <span className={`text-4xl font-black ${performance.color}`}>{performance.grade}</span>
              </div>
              <div className="w-full bg-white/5 rounded-full h-2 mb-2">
                <div 
                  className={`h-full rounded-full transition-all duration-1000 ${percentage >= 70 ? 'bg-blue-500' : 'bg-red-500'}`}
                  style={{ width: `${percentage}%` }}
                />
              </div>
              <p className="text-center text-xs font-bold text-slate-300 mt-2">{performance.desc}</p>
            </div>

            <div className="space-y-2">
              <h3 className="text-xs font-bold text-slate-400 uppercase tracking-tight flex items-center gap-2">
                <LayoutList size={14} /> Task Summary
              </h3>
              <div className="space-y-2 max-h-60 overflow-y-auto pr-2 scrollbar-thin">
                {dayData.tasks.map(t => (
                  <div key={t.id} className="flex items-center justify-between text-xs p-2 rounded-lg bg-white/5">
                    <span className={t.completed ? 'text-slate-300 line-through' : 'text-slate-400'}>{t.title}</span>
                    {t.completed ? <CheckCircle2 size={14} className="text-blue-500" /> : <XCircle size={14} className="text-red-500" />}
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="space-y-3">
             <label className="text-xs font-bold text-slate-400 uppercase tracking-tight">Today's Reflection</label>
             <textarea 
               value={note}
               onChange={(e) => setNote(e.target.value)}
               placeholder="How was today? What did you learn?"
               className="w-full h-32 glass bg-white/5 rounded-xl p-4 text-sm text-slate-200 outline-none focus:border-blue-500/50 transition-colors resize-none"
             />
          </div>
        </div>

        {/* Right Panel: Planning */}
        <div className="w-full md:w-7/12 p-8 flex flex-col overflow-y-auto scrollbar-thin">
          <div className="flex items-center gap-3 mb-8">
            <div className="w-10 h-10 rounded-xl bg-purple-600/20 flex items-center justify-center text-purple-400">
              <CalendarPlus size={20} />
            </div>
            <div>
              <h2 className="text-xl font-bold">Plan Tomorrow</h2>
              <p className="text-[10px] text-slate-400 uppercase tracking-widest font-bold">Preparation & Focus</p>
            </div>
          </div>

          <div className="flex-1 space-y-6">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">English Focus</label>
                <input 
                   type="text"
                   value={plan.englishTopic}
                   onChange={(e) => setPlan({...plan, englishTopic: e.target.value})}
                   placeholder="e.g. Vocabulary Set #5"
                   className="w-full glass bg-white/5 rounded-xl p-3 text-sm text-slate-200 outline-none focus:border-blue-500/50"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Trading Strategy</label>
                <input 
                   type="text"
                   value={plan.tradingStrategy}
                   onChange={(e) => setPlan({...plan, tradingStrategy: e.target.value})}
                   placeholder="e.g. Fibonacci Breakout"
                   className="w-full glass bg-white/5 rounded-xl p-3 text-sm text-slate-200 outline-none focus:border-blue-500/50"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">DSA Topic</label>
                <input 
                   type="text"
                   value={plan.dsaTopic}
                   onChange={(e) => setPlan({...plan, dsaTopic: e.target.value})}
                   placeholder="e.g. Dynamic Programming"
                   className="w-full glass bg-white/5 rounded-xl p-3 text-sm text-slate-200 outline-none focus:border-blue-500/50"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Development Target</label>
                <input 
                   type="text"
                   value={plan.flutterReactChapter}
                   onChange={(e) => setPlan({...plan, flutterReactChapter: e.target.value})}
                   placeholder="e.g. State Management"
                   className="w-full glass bg-white/5 rounded-xl p-3 text-sm text-slate-200 outline-none focus:border-blue-500/50"
                />
              </div>
            </div>

            <div className="glass-card p-6 border-blue-500/10 bg-blue-600/5 mt-8">
              <div className="flex gap-4">
                <Award className="text-blue-400 mt-1" size={24} />
                <div>
                  <h4 className="font-bold text-white mb-1">Consistency creates Champions</h4>
                  <p className="text-xs text-slate-400 leading-relaxed">
                    By planning tonight, you reduce decision fatigue tomorrow morning. Lock 
                    in your focus and sleep with a clear mind.
                  </p>
                </div>
              </div>
            </div>
          </div>

          <div className="mt-8 flex gap-4">
             <button 
               onClick={onClose}
               className="flex-1 py-4 rounded-2xl glass hover:bg-white/5 font-bold text-sm transition-all"
             >
               CANCEL
             </button>
             <button 
               onClick={() => onComplete(note, plan)}
               className="flex-[2] py-4 rounded-2xl bg-gradient-to-r from-blue-600 to-purple-600 hover:scale-[1.02] active:scale-[0.98] font-bold text-sm text-white shadow-xl shadow-blue-500/20 transition-all flex items-center justify-center gap-2"
             >
               <Send size={16} /> LOCK & SLEEP
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NightReview;
